(* [comment removed for export] *)
Definition crs_segC_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (A own lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + 48)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' A (SvcHdrCells (ssvc_hdr0 own))
    /\ ACONST m'.

Lemma crs_segC : forall (pcv sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (rax s0x s2x s3x s4x rav s0v s1v s2v s3v s4v : word) (F : bvmap 5 word) fc (m : mem) (A own allocb lo : Z) (j8 : list byte),
  (pcv = Z_to_bv 64 P_A_CRS_RET2 \/ pcv = ret_pc (Z_to_bv 64 P_A_CRS_RET2)) ->
  rw_cells asegs m (bv_unsigned sp + -80) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 (Z_to_bv 64 2147450880); C8 (Z_to_bv 64 P_A_CRS_RET0)] ->
  rw_cells asegs m (bv_unsigned sp + -32) [CB 8 j8; C8 (Z_to_bv 64 allocb); C8 s0v; C8 rav] ->
  rw_cells asegs m A (SvcHdrCells (mkSVC AVP_SSVC 0 0 own 0 0)) ->
  0 <= own < 2^64 ->
  stk asegs m lo (bv_unsigned sp + -80) -> lo + 80 <= bv_unsigned sp -> aceil <= lo ->
  rblock_range A NEWSZ_SSVC -> addressable m A NEWSZ_SSVC ->
  bv_unsigned rav mod 2 = 0 ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (crs_segC_post rav sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F fc A own lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
             s0x (Z_to_bv 64 A) a0 a1 a2 a3 a4 a5 a6 a7
             s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F pcv fc None m (seg_rom asegs)).
